std::vector<Node> nodes;
for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    // Skip infinite vertices (should not appear in finite_vertices, but guard anyway)
    if (rt.is_infinite(vit)) continue;

    // Original geometric data
    const auto& point = vit->point();                     // CGAL::Point_3
    const auto& info  = vit->info();                      // assumed to contain velocity (Vector_3) and mass (double)

    // Compute maximal incident edge length
    double max_len = 0.0;
    auto circ = rt.incident_vertices(vit);
    if (circ != nullptr) {
        auto start = circ;
        do {
            if (!rt.is_infinite(circ)) {
                double len = std::sqrt(CGAL::squared_distance(point, circ->point()));
                if (len > max_len) max_len = len;
            }
            ++circ;
        } while (circ != start);
    }

    // Classify node type based on the threshold
    NodeType type = (max_len > threshold) ? NodeType::Boundary : NodeType::Interior;

    // Propagate position to the requested time using velocity
    auto position_at_time = point + info.velocity * time;   // CGAL supports Point + Vector*scalar

    // Assemble node
    nodes.push_back(Node{
        position_at_time,   // position
        info.velocity,      // velocity
        info.mass,          // mass
        type                 // classification
    });
}
return nodes;

